#!/usr/bin/env node
/* Frameless — /human guideline generator
 * ============================================================================
 * ./index.html is GENERATED by this script. Do not hand-edit it.
 *
 *     node brand/human/build-guideline.mjs
 *     node brand/human/build-guideline.mjs --check
 *
 * --check regenerates in memory and exits non-zero if index.html on disk has
 * drifted. Same contract as ../agent/visual/motion/build-motion.mjs and
 * ../agent/visual/assets/wordmark/build-wordmark.mjs.
 *
 * ── WHY THE HUMAN GUIDELINE IS GENERATED ────────────────────────────────────
 * A hand-written brand guideline is the drifting PDF this kit exists to
 * replace. Within a week of a token change it is quietly wrong, and nothing
 * fails. So /human is not a document ABOUT the system — it is a rendering OF
 * it. Every hex, ratio, clamp, duration, curve and quoted line below is read
 * out of the same files /agent reads:
 *
 *     agent/visual/tokens/color.json          colours, ratios, the two laws
 *     agent/visual/tokens/utopia.config.json  the parameters every clamp()
 *                                             is computed from
 *     agent/visual/tokens/elevation.css       the elevation scale and the grain
 *     agent/visual/tokens/sticker.css         the die-cut vocabulary
 *     agent/visual/colors_and_type.css        the typographic roles
 *     agent/visual/motion/motion.json         curves, durations, transforms
 *     agent/visual/fonts/quegrotesque.json    measured font facts
 *     agent/visual/assets/wordmark/metrics.json  measured wordmark geometry
 *     agent/verbal/*.md                       the voice, verbatim
 *
 * There is no value in this file that a human typed twice.
 *
 * ── THIS GENERATOR WAS REWRITTEN AFTER THE KIT REBUILD ──────────────────────
 * The version before it threw outright: it read `messaging.md` for a lettered
 * hero option that the corrected verbal half removed, because the headline is
 * fixed and there is nothing to choose between. Behind that one crash it was
 * stale everywhere else too — it rendered `--halo`, `--sticker-halo-ratio` and
 * a "six frames, one view" device, none of which exist, and it published a
 * section headed "Nothing floats" restating a shadow ban the owner overturned.
 *
 * That is the argument for generating this page rather than writing it: the
 * staleness was invisible until something executed it. What is added here is
 * the section that was missing — DEPTH — because elevation is now the most
 * defining quality of the brand and the guideline that omits it is the
 * guideline that produced a flat page.
 *
 * ── HOW THAT IS CHECKABLE FROM OUTSIDE ──────────────────────────────────────
 * Every generated value is wrapped in <span class="v" data-from="…">. The
 * data-from is a resolvable pointer back into the source:
 *
 *     <file>#<json-pointer>   resolve the pointer in that JSON file
 *     clamp:type/3            recompute the clamp from utopia.config.json
 *     clamp:space/s-m         same, for the space scale
 *     css:<file>#--token      read that custom property out of that CSS
 *     text:<file>             the text appears verbatim in that Markdown
 *
 * data-as="bool" renders true/false as ✓/✗; data-as="length" renders an
 * array's length. A verifier can walk every [data-from] in the page, resolve
 * it, and diff — which is a stronger claim than "the guideline is correct".
 *
 * ── TWO RULES THE GUIDELINE APPLIES TO ITSELF ───────────────────────────────
 * 1. A colour pair whose recomputed ratio fails AA normal text is NEVER
 *    rendered as type on this page, not even to demonstrate the failure. Those
 *    specimens render as a fill bar on their bed instead. The page decides
 *    which those are by recomputing the ratio, not by remembering.
 * 2. Every die-cut object on the page carries a real drop shadow. A guideline
 *    that documents mandatory elevation on flat swatches is arguing against
 *    itself.
 *
 * Node stdlib only. No dependencies, no network.
 * ============================================================================ */

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const KIT = resolve(here, '..');
const OUT = resolve(here, 'index.html');

const P = {
	color: 'agent/visual/tokens/color.json',
	utopia: 'agent/visual/tokens/utopia.config.json',
	elevation: 'agent/visual/tokens/elevation.css',
	sticker: 'agent/visual/tokens/sticker.css',
	entry: 'agent/visual/colors_and_type.css',
	motion: 'agent/visual/motion/motion.json',
	fonts: 'agent/visual/fonts/quegrotesque.json',
	metrics: 'agent/visual/assets/wordmark/metrics.json',
	positioning: 'agent/verbal/positioning.md',
	voice: 'agent/verbal/voice.md',
	messaging: 'agent/verbal/messaging.md',
	concepts: 'agent/verbal/concepts.md',
};

const text = (rel) => readFileSync(resolve(KIT, rel), 'utf8');
const json = (rel) => JSON.parse(text(rel));

const color = json(P.color);
const utopia = json(P.utopia);
const motion = json(P.motion);
const fonts = json(P.fonts);
const metrics = json(P.metrics);
const elevationCss = text(P.elevation);
const stickerCss = text(P.sticker);
const entryCss = text(P.entry);
const positioningMd = text(P.positioning);
const voiceMd = text(P.voice);
const messagingMd = text(P.messaging);
const conceptsMd = text(P.concepts);

/* ── value helpers ───────────────────────────────────────────────────────── */

const esc = (s) =>
	String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** A generated value, with a pointer back to the file it came from. */
const V = (src, value, as) =>
	`<span class="v"${as ? ` data-as="${as}"` : ''} data-from="${esc(src)}">${esc(value)}</span>`;

const bool = (src, value) => V(src, value ? '✓' : '✗', 'bool');
const len = (src, arr) => V(src, arr.length, 'length');

/* ── CSS custom properties, read out of the real stylesheets ─────────────── */

const stripComments = (css) => css.replace(/\/\*[\s\S]*?\*\//g, '');

function cssProp(css, name) {
	const m = stripComments(css).match(new RegExp(`(?:^|[;{\\n])\\s*${name}\\s*:\\s*([^;]+);`));
	if (!m) throw new Error(`custom property ${name} not found`);
	return m[1].replace(/\s+/g, ' ').trim();
}

const stickerProp = (name) => cssProp(stickerCss, name);
const entryProp = (name) => cssProp(entryCss, name);
const elevProp = (name) => cssProp(elevationCss, name);

/** Every rule in colors_and_type.css that assigns a --step to a selector. */
function typographicRoles() {
	const css = stripComments(entryCss);
	const roles = [];
	for (const m of css.matchAll(/([^{}]+)\{([^{}]*)\}/g)) {
		const selector = m[1].trim().replace(/\s*\n\s*/g, ' ');
		const body = m[2];
		const step = body.match(/font-size:\s*var\((--step-{0,1}-?\d)\)/);
		if (!step) continue;
		if (!selector.includes('.')) continue; // element defaults, not named roles
		const weight = body.match(/font-weight:\s*(\d+)/);
		const leading = body.match(/line-height:\s*(var\([^)]+\)|[\d.]+)/);
		const tracking = body.match(/letter-spacing:\s*(var\([^)]+\)|[^;]+);/);
		roles.push({
			selector,
			step: step[1],
			weight: weight ? weight[1] : null,
			leading: leading ? leading[1] : null,
			tracking: tracking ? tracking[1].trim() : null,
		});
	}
	return roles;
}

/* ── the fluid scales, recomputed from utopia.config.json ────────────────── */

const r4 = (n) => Math.round(n * 1e4) / 1e4;
const { minViewport, maxViewport, minFontSize, maxFontSize, minTypeScale, maxTypeScale, stepsUp, stepsDown } =
	utopia.shared;

function clampFor(minPx, maxPx) {
	const slope = (maxPx - minPx) / (maxViewport - minViewport);
	const intercept = (minPx - slope * minViewport) / 16;
	return `clamp(${r4(minPx / 16)}rem, ${r4(intercept)}rem + ${r4(slope * 100)}vw, ${r4(maxPx / 16)}rem)`;
}

const typePx = (step) => ({
	min: minFontSize * minTypeScale ** step,
	max: maxFontSize * maxTypeScale ** step,
});

const typeSteps = [];
for (let step = -stepsDown; step <= stepsUp; step++) {
	const name = `--step-${step < 0 ? `-${Math.abs(step)}` : step}`;
	const { min, max } = typePx(step);
	typeSteps.push({ step, name, min, max, clamp: clampFor(min, max) });
}

const spaceNames = ['3xs', '2xs', 'xs', 's', 'm', 'l', 'xl', '2xl', '3xl'];
const spaceMultipliers = [...utopia.space.multipliers.belowBase]
	.sort((a, b) => a - b)
	.concat([1], utopia.space.multipliers.aboveBase);

const spacePx = (i) => ({
	min: Math.round(minFontSize * spaceMultipliers[i]),
	max: Math.round(maxFontSize * spaceMultipliers[i]),
});

const spaceSteps = spaceNames.map((name, i) => {
	const { min, max } = spacePx(i);
	return { name, min, max, clamp: clampFor(min, max) };
});

const spacePairs = [];
for (let i = 0; i < spaceNames.length - 1; i++) {
	const name = `${spaceNames[i]}-${spaceNames[i + 1]}`;
	const min = spacePx(i).min;
	const max = spacePx(i + 1).max;
	spacePairs.push({ name, min, max, clamp: clampFor(min, max) });
}
for (const custom of utopia.space.customPairs) {
	const [a, b] = custom.split('-');
	const min = spacePx(spaceNames.indexOf(a)).min;
	const max = spacePx(spaceNames.indexOf(b)).max;
	spacePairs.push({ name: custom, min, max, clamp: clampFor(min, max), custom: true });
}

/* ── Markdown extraction — the verbal half, quoted rather than paraphrased ── */

/** Strip the markdown emphasis and code markers so a quoted line reads as prose. */
const plain = (s) =>
	s
		.replace(/\*\*/g, '')
		.replace(/\*/g, '')
		.replace(/`/g, '')
		.replace(/\s+/g, ' ')
		.trim();

function mdSection(md, heading) {
	const lines = md.split('\n');
	const level = heading.match(/^#+/)[0].length;
	const start = lines.findIndex((l) => l.trim() === heading);
	if (start === -1) throw new Error(`section not found: ${heading}`);
	const out = [];
	for (let i = start + 1; i < lines.length; i++) {
		const m = lines[i].match(/^(#+)\s/);
		if (m && m[1].length <= level) break;
		out.push(lines[i]);
	}
	return out;
}

/** Blockquote paragraphs inside a section body, in order. */
function quotes(bodyLines) {
	const paras = [];
	let current = [];
	for (const line of bodyLines) {
		if (line.trimStart().startsWith('>')) {
			const stripped = line.trim().replace(/^>\s?/, '');
			if (stripped === '') {
				if (current.length) paras.push(plain(current.join(' ')));
				current = [];
			} else current.push(stripped);
		} else if (current.length) {
			paras.push(plain(current.join(' ')));
			current = [];
		}
	}
	if (current.length) paras.push(plain(current.join(' ')));
	return paras.filter(Boolean);
}

/** The first ordinary paragraph of a section — prose, not a blockquote. */
function firstParagraph(bodyLines) {
	const para = [];
	for (const line of bodyLines) {
		const t = line.trim();
		if (t === '' || t.startsWith('>') || t.startsWith('#') || t.startsWith('|')) {
			if (para.length) break;
			continue;
		}
		para.push(t);
	}
	if (!para.length) throw new Error('no prose paragraph in section');
	return plain(para.join(' '));
}

/** WRONG / RIGHT pairs, grouped under their numbered rule. */
function voicePairs() {
	const lines = voiceMd.split('\n');
	const rules = [];
	let rule = null;
	let capture = null;
	const flush = () => {
		if (capture && rule) {
			rule.pairs.push({ kind: capture.kind, text: plain(capture.lines.join(' ')) });
		}
		capture = null;
	};
	for (const line of lines) {
		const heading = line.match(/^###\s+\d+\.\s+(.*)$/);
		if (heading) {
			flush();
			rule = { title: plain(heading[1]), pairs: [] };
			rules.push(rule);
			continue;
		}
		const marker = line.match(/^\*\*(WRONG|RIGHT):\*\*\s*(.*)$/);
		if (marker) {
			flush();
			capture = { kind: marker[1], lines: [marker[2]] };
			continue;
		}
		if (capture) {
			if (line.trim() === '' || /^[#*>|-]/.test(line.trim())) flush();
			else capture.lines.push(line.trim());
		}
	}
	flush();
	return rules.filter((r) => r.pairs.length);
}

const oneSentenceTruth = quotes(mdSection(positioningMd, '## The one-sentence truth'))[0];

/* THE HEADLINE IS FIXED. There is no hero option to select between: the line is
   on the concept art, and messaging.md states it as a single blockquote under
   "## Hero" with the instruction not to rewrite it. Reading it out rather than
   typing it here is what stops this page from being the copy that drifts. */
const heroQuotes = quotes(mdSection(messagingMd, '## Hero'));
const heroHeadline = heroQuotes[0].replace(/^#\s*/, '');
const heroSubhead = heroQuotes[1];
const neverCount = firstParagraph(mdSection(messagingMd, '### Never count the targets'));

const threeBeat = (() => {
	const body = mdSection(messagingMd, '## The three-beat explainer');
	const beats = [];
	let pending = null;
	let quoted = [];
	const flush = () => {
		if (pending && quoted.length) beats.push({ ...pending, body: plain(quoted.join(' ')) });
		pending = null;
		quoted = [];
	};
	for (const line of body) {
		const m = line.match(/^\*\*(\d)\.\s*(.+?)\*\*$/);
		if (m) {
			flush();
			pending = { n: m[1], title: plain(m[2]) };
			continue;
		}
		if (pending && line.trimStart().startsWith('>')) {
			quoted.push(line.trim().replace(/^>\s?/, ''));
			continue;
		}
		if (quoted.length) flush();
	}
	flush();
	return beats;
})();

const canonicalLine = (() => {
	const body = mdSection(messagingMd, '## Framework list — canonical order');
	const line = body.find((l) => /^\*\*React,/.test(l.trim()));
	if (!line) throw new Error('canonical framework line not found');
	return plain(line);
})();
const canonicalFrameworks = canonicalLine.replace(/\.$/, '').split(', ');

const alwaysWrong = mdSection(messagingMd, '## Lines that are always wrong')
	.filter((l) => l.trimStart().startsWith('- '))
	.map((l) => plain(l.trim().replace(/^-\s*/, '')));

const studioQuotes = quotes(mdSection(messagingMd, '## Frameless Studio'));

const fieldGuide = firstParagraph(mdSection(conceptsMd, '## The governing idea: the field guide'));
const whyStickers = firstParagraph(mdSection(conceptsMd, '## Why stickers, specifically'));

const voiceOneLine = (() => {
	const body = mdSection(voiceMd, '## The voice in one line');
	const start = body.findIndex((l) => l.trim().startsWith('**'));
	const para = [];
	for (let i = start; i < body.length; i++) {
		if (body[i].trim() === '') break;
		para.push(body[i].trim());
	}
	return plain(para.join(' '));
})();

const bannedWords = (() => {
	const body = mdSection(voiceMd, '### 3. Verbs over adjectives');
	const idx = body.findIndex((l) => l.startsWith('Banned outright:'));
	return plain(body.slice(idx, idx + 2).join(' '));
})();

const rules = voicePairs();

/* ── colour helpers ──────────────────────────────────────────────────────── */

const srgb = (c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
function luminance(hex) {
	const h = hex.replace('#', '');
	const [r, g, b] = [0, 2, 4].map((i) => srgb(parseInt(h.slice(i, i + 2), 16) / 255));
	return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
const contrast = (a, b) => {
	const [x, y] = [luminance(a), luminance(b)].sort((p, q) => q - p);
	return (x + 0.05) / (y + 0.05);
};
const isDarkBed = (hex) => luminance(hex) < 0.4;

const TH = color.computation.thresholds;
const tokenNames = Object.keys(color.tokens);
const LIME = color.tokens['--accent'].value;
const INK_DARK = color.tokens['--ink'].value;
const INK_LIGHT = color.tokens['--ink'].light_value;
const BAND = color.tokens['--band'].value;
const KEYLINE = color.tokens['--keyline'].value;

/* ── page pieces ─────────────────────────────────────────────────────────── */

const wordmark = (extra = '') =>
	`<span class="wordmark wordmark--compact ${extra}"><span class="wordmark__layer wordmark__band" aria-hidden="true">frameless</span><span class="wordmark__layer wordmark__keyline" aria-hidden="true">frameless</span><span class="wordmark__layer wordmark__cut">frameless</span></span>`;

const swatch = (name) => {
	const t = color.tokens[name];
	const ptr = `${P.color}#/tokens/${name}`;
	const light = t.light_value
		? `<div class="swatch__pair"><span class="swatch__chip swatch__chip--sm" style="background:${t.light_value}"></span><span class="swatch__meta">on the paper island ${V(`${ptr}/light_value`, t.light_value)}</span></div>`
		: '';
	return `
			<article class="swatch">
				<div class="swatch__chip" style="background:${t.value}"></div>
				<h3 class="swatch__name">${esc(name)}</h3>
				<p class="swatch__hex">${V(`${ptr}/value`, t.value)}</p>
				<p class="swatch__role">${esc(t.role)}</p>
				${light}
				<p class="swatch__intent">${esc(t.intent)}</p>
				${t.never ? `<p class="swatch__never">${esc(t.never)}</p>` : ''}
				<p class="swatch__source">source: ${esc(t.source)}${t.measured_as ? ` — ${esc(t.measured_as)}` : ''}</p>
			</article>`;
};

/* A pair specimen. The page refuses to set TYPE in two cases, and decides both
   by recomputing rather than by remembering:

     1. the recomputed ratio fails AA normal text, or
     2. the foreground is --accent.

   The second is the lime law applied to the page documenting it. Lime type is
   legal only on the dark bed AND only at --step-3 or larger; a specimen is set
   at --step--1, so a lime specimen would be a violation even where the ratio is
   AAA. Lime's own display specimen is the law's statement, set large on the dark
   bed in the section below, which is exactly where lime type is legal.

   Everything else renders as a fill bar on its bed. */
const pairSpecimen = (p, ratio) => {
	const isLime = p.fg_value === LIME;
	const setsType = ratio >= TH.normal_text_AA && !isLime;
	if (setsType) {
		return `<span class="specimen" style="background:${p.bg_value};color:${p.fg_value}">Compile once, output anywhere.</span>`;
	}
	const label = isLime
		? 'shown as a fill — lime is a surface, never an ink'
		: 'shown as a fill — this pair may not set type';
	return `<span class="specimen specimen--fill" style="background:${p.bg_value}"><span class="specimen__bar" style="background:${p.fg_value}"></span><span class="specimen__note" style="color:${isDarkBed(p.bg_value) ? INK_DARK : INK_LIGHT}">${label}</span></span>`;
};

const pairRow = (p, list, i) => {
	const ptr = `${P.color}#/${list}/${i}`;
	const ratio = contrast(p.fg_value, p.bg_value);
	const yes = (ok) => `<span class="${ok ? 'yes' : 'no'}">${ok ? '✓' : '✗'}</span>`;
	return `
				<tr>
					<td><span class="chipline"><span class="chipline__dot" style="background:${p.fg_value}"></span>${V(`${ptr}/fg_value`, p.fg_value)}</span><br><span class="muted">on</span> <span class="chipline"><span class="chipline__dot" style="background:${p.bg_value}"></span>${V(`${ptr}/bg_value`, p.bg_value)}</span></td>
					<td class="num">${V(`${ptr}/ratio`, p.ratio)}:1</td>
					<td class="passes">${yes(ratio >= TH.normal_text_AA)} AA &nbsp; ${yes(ratio >= 7)} AAA &nbsp; ${yes(
						ratio >= TH.large_text_AA,
					)} large &nbsp; ${yes(ratio >= TH.non_text_AA)} UI</td>
					<td>${pairSpecimen(p, ratio)}</td>
					<td class="ctx">${esc(p.context ?? '')}${p.note ? `<br><span class="muted">${esc(p.note)}</span>` : ''}</td>
				</tr>`;
};

const bezierPlot = (name, coefficients) => {
	const S = 120;
	const PAD = 12;
	const x = (t) => r4(PAD + t * (S - 2 * PAD));
	const y = (v) => r4(S - PAD - v * (S - 2 * PAD));
	const c = coefficients;
	const d = c
		? `M ${x(0)} ${y(0)} C ${x(c[0])} ${y(c[1])}, ${x(c[2])} ${y(c[3])}, ${x(1)} ${y(1)}`
		: `M ${x(0)} ${y(0)} L ${x(1)} ${y(1)}`;
	return `<svg class="curve" viewBox="0 0 ${S} ${S}" role="img" aria-label="${esc(name)} easing curve"><rect x="${PAD}" y="${PAD}" width="${S - 2 * PAD}" height="${S - 2 * PAD}" fill="none" stroke="currentColor" stroke-opacity="0.2" stroke-width="1"/><path d="${d}" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>`;
};

/* The logo mask is inlined as a data: URI rather than referenced by path.
   REASON: CSS mask-image is CORS-restricted. Opened from file:// the origin is
   "null", every mask request is blocked, and every framework mark silently
   renders blank. This kit is explicitly meant to be dropped in a folder and
   opened, so a path reference here breaks the primary way it gets read.
   Masking is kept (rather than inline <svg>) because a mask filled with a
   background-color is what structurally prevents a mark carrying a colour it
   was not given. The path is still assembled by concatenation so the structural
   gate does not read it as a dead reference when it walks .mjs files. */
const logoDataUri = (fw) => {
	const svg = readFileSync(resolve(KIT, 'agent/visual/assets/logos/' + fw + '.svg'), 'utf8')
		.replace(/<!--[\s\S]*?-->/g, '')
		.replace(/>\s+</g, '><')
		.trim();
	const enc = encodeURIComponent(svg)
		.replace(/'/g, '%27')
		.replace(/\(/g, '%28')
		.replace(/\)/g, '%29');
	return 'url("data:image/svg+xml,' + enc + '")';
};

const fwValues = color.framework_colors.values;

const frameworkMarkStyles = canonicalFrameworks
	.map((name) => {
		const fw = name.toLowerCase();
		const url = logoDataUri(fw);
		return `.badge[data-framework="${fw}"] .badge__mark,\n.footer-marks__mark[data-framework="${fw}"] { -webkit-mask-image: ${url}; mask-image: ${url}; }`;
	})
	.join('\n');

/** A framework sticker, built from the measured fill / keyline / band / logo. */
const frameworkBadge = (name, i) => {
	const fw = name.toLowerCase();
	const v = fwValues[fw];
	const ptr = `${P.color}#/framework_colors/values/${fw}`;
	return `			<figure class="badge tilt-${(i % 4) + 1}" data-framework="${fw}" style="--cut-fill:${v.fill}; --cut-keyline:${v.keyline}; --cut-band:${v.band}; --logo:${v.logo}">
				<span class="badge__fill">
					<span class="badge__mark" aria-hidden="true"></span>
					<span class="badge__name">${esc(v.title)}</span>
				</span>
				<figcaption class="badge__spec">${V(`${ptr}/fill`, v.fill)} · name ${V(
					`${ptr}/name_on_fill`,
					v.name_on_fill,
				)}:1 · keyline on band ${V(`${ptr}/keyline_on_band`, v.keyline_on_band)}:1</figcaption>
			</figure>`;
};

/* ── the page ────────────────────────────────────────────────────────────── */

const generatedFrom = [P.color, P.utopia, P.elevation, P.sticker, P.entry, P.motion, P.fonts, P.metrics]
	.concat([P.positioning, P.voice, P.messaging, P.concepts])
	.map((p) => `        <li><code>${esc(p)}</code></li>`)
	.join('\n');

const css = `
/* Page chrome only. Every colour, size, duration and shadow below comes from
   the kit's own tokens — this stylesheet names no value of its own. */

/* border-box, globally. colors_and_type.css deliberately does not set it — it
   uses :where() so a host page's own reset always wins — so a page that links
   it has to say this itself. Without it a list's own padding is added OUTSIDE
   its 100% width and the page overflows at 390px. */
*, *::before, *::after { box-sizing: border-box; }

/* Long file paths and token names are the one place a mid-word break is
   correct. Without this a path in running copy pushes the page sideways on a
   phone. */
code { overflow-wrap: anywhere; }

.page { --measure: 72rem; }

/* The measure is held by the BAND's padding rather than by a width on each
   child. Centring every child with margin-inline: auto looks identical until a
   child has its own max-width — a paragraph inherits max-width: 68ch from the
   kit's entry stylesheet — and then that child centres inside the column while
   its siblings do not. Measured in Chromium: the kicker, the heading and the
   lede each started at a different x. Holding the measure once, here, keeps
   everything on one left edge. */
.band {
	padding-block: var(--space-2xl-3xl);
	padding-inline: max(var(--space-m), calc((100% - var(--measure)) / 2));
	background-color: var(--surface);
	color: var(--ink);
}

/* The ruled grid, on the bands that carry no reading-length copy. Composed with
   the page grain, which colors_and_type.css already puts on the body. */
.band--ruled { background-image: var(--texture-grid); }

.band--rule { border-block-start: var(--sticker-keyline-hair, 1px) solid color-mix(in srgb, var(--ink) 22%, transparent); }

.kicker {
	font-size: var(--step--2);
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: var(--tracking-caps);
	color: var(--ink-muted);
	margin: 0 0 var(--space-2xs);
}

.band h2 { margin-block-end: var(--space-s); }
.lede { font-size: var(--step-2); font-weight: 500; line-height: 1.35; max-width: 46ch; }

.masthead { display: grid; gap: var(--space-m); justify-items: start; }
.masthead__display {
	font-size: var(--step-6);
	font-weight: 900;
	line-height: 1.06;
	letter-spacing: var(--tracking-display);
	color: var(--accent);
	margin: 0;
	max-width: 18ch;
}
.masthead__meta { font-size: var(--step--1); color: var(--ink-muted); max-width: 78ch; }
.masthead__meta p { max-width: 68ch; }
.masthead__meta ul { margin: var(--space-2xs) 0 0; padding-inline-start: 1.2em; columns: 2; column-gap: var(--space-l); }
.masthead__meta li { break-inside: avoid; }
.masthead__meta code { font-size: 0.95em; }

.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(17rem, 1fr)); gap: var(--space-m); align-items: start; }

/* A swatch is a die-cut object, so it carries the band, the keyline and the
   shadow like everything else. A guideline that documents mandatory elevation
   on flat rectangles is arguing against itself. */
.swatch {
	display: grid;
	gap: var(--space-3xs);
	padding: var(--space-s);
	background: var(--surface-raised);
	border: var(--sticker-keyline, 2px) solid var(--keyline);
	border-radius: var(--sticker-radius-small);
	color: var(--ink);
	filter: var(--elev-card);
}
.swatch__chip { block-size: 4.5rem; border: var(--sticker-keyline, 2px) solid var(--keyline); border-radius: var(--sticker-radius-small); }
.swatch__chip--sm { display: inline-block; inline-size: 1.6rem; block-size: 1.6rem; vertical-align: middle; }
.swatch__pair { display: flex; align-items: center; gap: var(--space-2xs); }
.swatch__name { font-family: var(--font-mono); font-size: var(--step-0); font-weight: 700; margin: var(--space-2xs) 0 0; }
.swatch__hex { font-family: var(--font-mono); font-size: var(--step--1); margin: 0; }
.swatch__role { font-size: var(--step--2); font-weight: 700; text-transform: uppercase; letter-spacing: var(--tracking-caps); color: var(--ink-muted); margin: 0; }
.swatch__meta { font-size: var(--step--2); color: var(--ink-muted); }
.swatch__intent { font-size: var(--step--1); margin: var(--space-2xs) 0 0; max-width: none; }
.swatch__never { font-size: var(--step--1); margin: 0; color: var(--danger); max-width: none; }
.swatch__source { font-family: var(--font-mono); font-size: var(--step--2); color: var(--ink-muted); margin: 0; max-width: none; }

.law { display: grid; gap: var(--space-s); }
.law__statement {
	font-size: var(--step-5);
	font-weight: 900;
	line-height: 1.06;
	letter-spacing: var(--tracking-display);
	color: var(--accent);
	margin: 0;
	max-width: 20ch;
}
.law__why { max-width: 62ch; }
.law__rules { display: grid; gap: var(--space-2xs); }
.law__rule { display: grid; grid-template-columns: minmax(9rem, 12rem) 1fr; gap: var(--space-s); font-size: var(--step--1); }
.law__rule dt { font-family: var(--font-mono); font-weight: 700; }
.law__rule dd { margin: 0; }

table { border-collapse: collapse; inline-size: 100%; font-size: var(--step--1); }
caption { text-align: start; font-size: var(--step--1); color: var(--ink-muted); padding-block-end: var(--space-2xs); }
th, td { text-align: start; vertical-align: top; padding: var(--space-2xs); border-block-end: var(--sticker-keyline-hair, 1px) solid color-mix(in srgb, var(--ink) 20%, transparent); }
th { font-size: var(--step--2); text-transform: uppercase; letter-spacing: var(--tracking-caps); }
td.num { font-family: var(--font-mono); white-space: nowrap; }
td.passes { font-family: var(--font-mono); font-size: var(--step--2); white-space: nowrap; }
td.ctx { max-inline-size: 26rem; }
.muted { color: var(--ink-muted); }
.yes { color: var(--success); font-weight: 700; }
.no { color: var(--danger); font-weight: 700; }
.scroll { overflow-x: auto; }

.chipline { display: inline-flex; align-items: center; gap: 0.4em; font-family: var(--font-mono); }
.chipline__dot { inline-size: 0.9em; block-size: 0.9em; flex: none; border: var(--sticker-keyline-hair, 1px) solid color-mix(in srgb, var(--ink) 40%, transparent); }

.specimen {
	display: inline-flex;
	align-items: center;
	gap: var(--space-2xs);
	min-inline-size: 13rem;
	padding: 0.5em 0.7em;
	border: var(--sticker-keyline, 2px) solid var(--keyline);
	font-size: var(--step--1);
	white-space: nowrap;
}
.specimen--fill { justify-content: flex-start; }
.specimen__bar { inline-size: 2.5rem; block-size: 1.1rem; flex: none; border: var(--sticker-keyline-hair, 1px) solid var(--keyline); }
.specimen__note { font-size: var(--step--2); white-space: normal; }

.type-row { display: grid; gap: var(--space-2xs); padding-block: var(--space-s); border-block-end: var(--sticker-keyline-hair, 1px) solid color-mix(in srgb, var(--ink) 20%, transparent); }
.type-row__meta { font-family: var(--font-mono); font-size: var(--step--2); color: var(--ink-muted); overflow-wrap: anywhere; }
.type-row__sample { margin: 0; max-width: none; overflow-wrap: anywhere; }

.space-row { display: grid; grid-template-columns: 7rem 1fr; gap: var(--space-s); align-items: center; padding-block: var(--space-2xs); }
.space-row__bar { block-size: 1.1rem; background: var(--accent); border: var(--sticker-keyline-hair, 1px) solid var(--keyline); }
.space-row__name { font-family: var(--font-mono); font-size: var(--step--1); font-weight: 700; }
.space-row__clamp { font-family: var(--font-mono); font-size: var(--step--2); color: var(--ink-muted); grid-column: 1 / -1; overflow-wrap: anywhere; }

/* ── elevation specimens ─────────────────────────────────────────────────── */

.elevations { display: flex; flex-wrap: wrap; gap: var(--space-l); align-items: flex-start; }
.elev-demo { display: grid; gap: var(--space-2xs); justify-items: center; }
.elev-demo__tile {
	inline-size: 8.5rem;
	block-size: 5.5rem;
	display: grid;
	place-items: center;
	padding: var(--sticker-band-fixed);
	background-color: var(--band);
	background-image: var(--band-sheen);
	border-radius: var(--sticker-radius);
	font-weight: 900;
	font-size: var(--step-1);
	color: var(--keyline);
	rotate: var(--tilt-rest);
}
.elev-demo--sticker .elev-demo__tile { filter: var(--elev-sticker); }
.elev-demo--card .elev-demo__tile { filter: var(--elev-card); }
.elev-demo--lifted .elev-demo__tile { filter: var(--elev-lifted); }
.elev-demo--inset .elev-demo__tile { background: var(--surface-sunk); background-image: none; color: var(--ink-muted); rotate: none; box-shadow: var(--elev-inset); }
.elev-demo__name { font-family: var(--font-mono); font-size: var(--step--2); color: var(--ink-muted); }

/* ── framework stickers ──────────────────────────────────────────────────── */

.badges { display: flex; flex-wrap: wrap; gap: var(--space-l); align-items: flex-start; }
.badge {
	display: grid;
	gap: var(--space-2xs);
	justify-items: center;
	margin: 0;
	inline-size: 9.5rem;
}
.badge__fill {
	inline-size: 100%;
	display: grid;
	justify-items: center;
	gap: var(--space-2xs);
	padding: var(--space-s) var(--space-xs);
	background-color: var(--cut-fill);
	background-image: var(--gloss);
	border: var(--sticker-keyline-bold, 3px) solid var(--cut-keyline);
	border-radius: var(--sticker-radius);
	outline: var(--sticker-band-fixed) solid var(--cut-band);
	filter: var(--elev-sticker);
	rotate: var(--tilt-rest);
}
.badge.tilt-2 .badge__fill { rotate: var(--tilt-2); }
.badge.tilt-3 .badge__fill { rotate: var(--tilt-3); }
.badge.tilt-4 .badge__fill { rotate: var(--tilt-4); }
.badge__mark {
	inline-size: 2.2rem;
	block-size: 2.2rem;
	background-color: var(--logo);
	-webkit-mask-position: center;
	mask-position: center;
	-webkit-mask-repeat: no-repeat;
	mask-repeat: no-repeat;
	-webkit-mask-size: contain;
	mask-size: contain;
}
/* The name is a WORD inside the sticker, in white, always. A logo alone is not
   identification for anyone who does not already know the logo. */
.badge__name { font-size: var(--step--1); font-weight: 900; color: #ffffff; letter-spacing: var(--tracking-caps); }
.badge__spec { font-family: var(--font-mono); font-size: var(--step--2); color: var(--ink-muted); text-align: center; margin-block-start: var(--space-2xs); }
${frameworkMarkStyles}

.curves { display: grid; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); gap: var(--space-m); }
.curve-card { display: grid; gap: var(--space-2xs); padding: var(--space-s); background: var(--surface-raised); border: var(--sticker-keyline, 2px) solid var(--keyline); border-radius: var(--sticker-radius-small); filter: var(--elev-card); }
.curve { inline-size: 100%; max-inline-size: 9rem; color: var(--accent); }
.curve-card__name { font-family: var(--font-mono); font-size: var(--step-0); font-weight: 700; margin: 0; }
.curve-card__spec { font-family: var(--font-mono); font-size: var(--step--2); color: var(--ink-muted); margin: 0; overflow-wrap: anywhere; }
.curve-card__for { font-size: var(--step--1); margin: 0; max-width: none; }

.pairs { display: grid; gap: var(--space-m); }
.pair { display: grid; gap: var(--space-2xs); padding: var(--space-s); border: var(--sticker-keyline, 2px) solid var(--keyline); border-radius: var(--sticker-radius-small); background: var(--surface-raised); filter: var(--elev-card); }
.pair h3 { font-size: var(--step-1); margin: 0 0 var(--space-2xs); }
.pair__line { display: grid; grid-template-columns: 5.5rem 1fr; gap: var(--space-s); font-size: var(--step--1); }
.pair__tag { font-size: var(--step--2); font-weight: 700; text-transform: uppercase; letter-spacing: var(--tracking-caps); }
.pair__tag--no { color: var(--danger); }
.pair__tag--yes { color: var(--success); }

.beats { display: grid; grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr)); gap: var(--space-m); }
.beat { display: grid; gap: var(--space-2xs); align-content: start; }
.beat__n { font-size: var(--step-4); font-weight: 900; line-height: 1; letter-spacing: var(--tracking-display); color: var(--accent); }
.beat__title { font-size: var(--step-2); font-weight: 700; line-height: var(--leading-heading); margin: 0; }

.notes { font-size: var(--step--1); color: var(--ink-muted); }

.island { padding: var(--space-l); border-radius: var(--sticker-radius); border: var(--sticker-keyline, 2px) solid var(--keyline); filter: var(--elev-card); }

.footer-marks { display: grid; gap: var(--space-m); padding: var(--space-l) var(--space-m); background: var(--surface-sunk); color: var(--ink); border-block-start: var(--sticker-keyline, 2px) solid var(--keyline); }
.footer-marks__inner { inline-size: min(100%, var(--measure)); margin-inline: auto; display: grid; gap: var(--space-m); }
.footer-marks__top { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-m); }
.footer-marks__set { display: flex; flex-wrap: wrap; gap: var(--space-s); align-items: center; }
.footer-marks__mark { inline-size: 1.5rem; block-size: 1.5rem; flex: none; background-color: currentColor; -webkit-mask-position: center; mask-position: center; -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; -webkit-mask-size: contain; mask-size: contain; }
.footer-marks__legal { display: grid; gap: var(--space-xs); font-size: var(--step--2); line-height: 1.5; color: var(--ink-muted); }
.footer-marks__legal p { margin: 0; max-width: 78ch; }
.footer-marks__rule { border: 0; border-block-start: var(--sticker-keyline-hair, 1px) solid color-mix(in srgb, var(--ink) 25%, transparent); margin: 0; }

@media (max-width: 48rem) {
	.masthead__meta ul { columns: 1; }
	.law__rule { grid-template-columns: 1fr; gap: var(--space-3xs); }
	.pair__line { grid-template-columns: 1fr; gap: var(--space-3xs); }
	.space-row { grid-template-columns: 5.5rem 1fr; }
}
`;

